package com.osrsfliphub;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class FlipHubPanelValueFormatServiceTest {
    private final PanelValueFormat service = new PanelValueFormat();

    @Test
    public void formatGpSupportsIntegerAndLong() {
        assertEquals("N/A", service.formatGp((Integer) null));
        assertEquals("N/A", service.formatGp((Long) null));
        assertEquals("12,345 gp", service.formatGp(Integer.valueOf(12_345)));
        assertEquals("12,345 gp", service.formatGp(Long.valueOf(12_345L)));
    }

    @Test
    public void formatGpCompactAbbreviatesLargeValues() {
        assertEquals("N/A", service.formatGpCompact(null));
        assertEquals("9,994 gp", service.formatGpCompact(9_994L));
        assertEquals("10.0K gp", service.formatGpCompact(9_995L));
        assertEquals("705.3K gp", service.formatGpCompact(705_263L));
        assertEquals("11.04M gp", service.formatGpCompact(11_037_956L));
        assertEquals("2.15B gp", service.formatGpCompact(2_147_483_647L));
        assertEquals("-1.25M gp", service.formatGpCompact(-1_250_000L));
    }

    @Test
    public void formatGpCompactPromotesValuesThatWouldRoundToTheNextUnit() {
        assertEquals("1.00M gp", service.formatGpCompact(999_950L));
        assertEquals("999.9K gp", service.formatGpCompact(999_949L));
        assertEquals("1.00B gp", service.formatGpCompact(999_950_000L));
    }

    @Test
    public void formatPercentAndGpPerHourUseExpectedPrecision() {
        assertEquals("N/A", service.formatPercent(null));
        assertEquals("4.13%", service.formatPercent(4.125));
        assertEquals("N/A", service.formatGpPerHour(null));
        assertEquals("1,235 gp/hr", service.formatGpPerHour(1_234.5));
    }

    @Test
    public void formatNumberAndLimitHandleEdgeCases() {
        assertEquals("-1,000", service.formatNumber(-1_000));
        assertEquals("0 / 100", service.formatLimit(null, 100));
        assertEquals("9 / 100", service.formatLimit(9, 100));
        assertEquals("N/A", service.formatLimit(9, 0));
        assertEquals("N/A", service.formatLimit(9, null));
    }

    /**
     * A return too small to show at two decimals must not be rendered as a signed zero, and
     * must not claim there was no return. "-0.00%" was painted red; "0.00%" was painted green.
     */
    @Test
    public void formatPercentNeverPrintsASignedOrMisleadingZero() {
        assertEquals("<0.01%", service.formatPercent(0.004));
        assertEquals(">-0.01%", service.formatPercent(-0.004));
        assertEquals("0.00%", service.formatPercent(0.0));
        assertEquals("0.01%", service.formatPercent(0.005));
        assertEquals("-0.01%", service.formatPercent(-0.005));
    }

    @Test
    public void formatDurationAndAgeClockClampAndFormatTime() {
        assertEquals("N/A", service.formatDuration(null));
        assertEquals("01:01:01", service.formatDuration(3_661_000L));
        assertEquals("00:00:00", service.formatAgeClock(-1_000L));
        assertEquals("25:00:05", service.formatAgeClock(90_005_000L));
    }
}

