        );

        assertEquals(2, page);
        assertEquals(10, rendered.size());
        assertEquals(14, rendered.get(0).item_id);
        assertEquals(5, rendered.get(9).item_id);
    }

    @Test
    public void renderItemsKeepsOnlyTheRequestedRecipeKind() {
        StatsRender coordinator = new StatsRender();
