package com.osrsfliphub;

import javax.inject.*;

@Singleton
final class ItemEnrichment {
    private final long localLimitWindowMs = Const.LOCAL_LIMIT_WINDOW_MS;

    @Inject
    ItemEnrichment() {
    }

    private Integer getCachedGeLimit(int itemId) {
        GeLimit service = Bridge.get(GeLimit.class);
        return service != null ? service.getCachedGeLimit(itemId) : null;
    }

    private WikiPriceEntry getWikiPriceEntry(int itemId, boolean allowRefresh) {
        WikiPrice service = Bridge.get(WikiPrice.class);
        return service != null ? service.getPriceEntry(itemId, allowRefresh) : null;
    }

    void applyGuidePrices(FlipHubItem item, int itemId, boolean allowRefresh) {
        if (item == null || itemId <= 0) {
            return;
        }
        WikiPriceEntry entry = getWikiPriceEntry(itemId, allowRefresh);
        if (entry == null) {
            return;
        }
        // A price above max cash is left out, so its card shows N/A rather than a wrong number.
        if (entry.high != null && entry.high > 0 && entry.high <= Integer.MAX_VALUE) {
            item.instasell_price = entry.high.intValue();
        }
        if (entry.low != null && entry.low > 0 && entry.low <= Integer.MAX_VALUE) {
            item.instabuy_price = entry.low.intValue();
        }
        if (entry.highTime != null && entry.highTime > 0) {
            item.instasell_ts_ms = entry.highTime * 1000L;
        }
        if (entry.lowTime != null && entry.lowTime > 0) {
            item.instabuy_ts_ms = entry.lowTime * 1000L;
        }
    }

    void applyLocalTradeInfo(FlipHubItem item, TradeInfo info) {
        if (item == null || info == null) {
            return;
        }
        if (info.lastBuyPrice != null && info.lastBuyPrice > 0) {
            item.last_buy_price = info.lastBuyPrice;
            item.last_buy_ts_ms = info.lastBuyTs;
        }
        if (info.lastSellPrice != null && info.lastSellPrice > 0) {
            item.last_sell_price = info.lastSellPrice;
            item.last_sell_ts_ms = info.lastSellTs;
        }
    }

    void applyLocalLimitInfo(FlipHubItem item, int itemId, LimitInfo info) {
        if (item == null || itemId <= 0) {
            return;
        }
        Integer geLimit = getCachedGeLimit(itemId);
        if (geLimit == null || geLimit <= 0) {
            return;
        }

        item.ge_limit_total = geLimit;
        if (info != null && info.buyQty > 0) {
            int remaining = (int) Math.max(0L, geLimit - info.buyQty);
            item.ge_limit_remaining = remaining;
            if (info.firstBuyTs != null) {
                long resetAt = info.firstBuyTs + localLimitWindowMs;
                item.ge_limit_reset_ms = Math.max(0L, resetAt - System.currentTimeMillis());
            }
            else {
                item.ge_limit_reset_ms = 0L;
            }
        }
        else {
            item.ge_limit_remaining = geLimit;
            item.ge_limit_reset_ms = 0L;
        }
    }

    void applyMarginInfo(FlipHubItem item) {
        if (item == null) {
            return;
        }
        Integer buy = null;
        Integer sell = null;
        boolean hasLastBuy = item.last_buy_price != null && item.last_buy_price > 0;
        boolean hasLastSell = item.last_sell_price != null && item.last_sell_price > 0;
        boolean hasInstaBuy = item.instabuy_price != null && item.instabuy_price > 0;
        boolean hasInstaSell = item.instasell_price != null && item.instasell_price > 0;
        if (hasInstaBuy && hasInstaSell) {
            buy = item.instabuy_price;
            sell = item.instasell_price;
        } else if (hasLastBuy && hasLastSell) {
            buy = item.last_buy_price;
            sell = item.last_sell_price;
        } else if (hasLastSell && hasInstaBuy) {
            buy = item.instabuy_price;
            sell = item.last_sell_price;
        } else if (hasLastBuy && hasInstaSell) {
            buy = item.last_buy_price;
            sell = item.instasell_price;
        }
        if (buy == null || sell == null) {
            return;
        }
        // One margin, taxed the way the ledgers tax it, so what the card promises matches the
        // profit it later reports. The game rounds the tax per item and caps it, so the margin
        // is whole coins and margin x limit is a plain multiple of it. The previous version
        // took an exact two percent here and a floored two percent for ROI, and neither
        // capped, which overstated the margin on anything selling above 250M.
        long taxPerItem = GeTax.perItem(item.item_id, sell);
        long marginPerItem = (long) sell - taxPerItem - (long) buy;
        item.margin = (int) marginPerItem;
        item.roi_percent = buy > 0 ? (marginPerItem * 100.0) / buy : null;
        if (item.ge_limit_remaining != null) {
            item.margin_x_limit = marginPerItem * (long) item.ge_limit_remaining;
        } else if (item.ge_limit_total != null) {
            item.margin_x_limit = marginPerItem * (long) item.ge_limit_total;
        }
    }
}

