        return linkSessionGuard.resolveLinkedCredentials();
    }

    boolean isLinked() {
        return linkSessionGuard != null
            && linkSessionGuard.isLinked();
    }

    long resolveSelectedProfileKey() {
        return resolver.resolveSelectedProfileKey(profileSelection);
