package com.osrsfliphub;

import java.util.Map;
import net.runelite.api.*;

final class OfferUpdateStampLegacyMatcher {
    boolean matchesCurrentOffers(Map<Integer, Stamp> stamps, GrandExchangeOffer[] offers) {
        if (stamps == null || stamps.isEmpty() || offers == null || offers.length == 0) {
            return false;
        }

        int compared = 0;
        int matches = 0;
        for (Map.Entry<Integer, Stamp> entry : stamps.entrySet()) {
            if (entry == null || entry.getKey() == null || entry.getValue() == null) {
                continue;
            }
            int slot = entry.getKey();
            if (slot < 0 || slot >= offers.length) {
                continue;
            }
            Stamp stamp = entry.getValue();
            if (stamp.itemId <= 0) {
                continue;
            }
            GrandExchangeOffer offer = offers[slot];
            if (offer == null || offer.getState() == GrandExchangeOfferState.EMPTY || offer.getItemId() <= 0) {
                continue;
            }
            compared++;
            boolean isBuy = OfferUpdateStampStateHelpers.isBuyOffer(offer);
            if (stamp.itemId == offer.getItemId() && stamp.isBuy == isBuy) {
                matches++;
            }
        }

        if (compared <= 0) {
            return false;
        }
        int required = compared >= 2 ? 2 : 1;
        return matches >= required;
    }
}

