@Singleton
final class ItemLookup {
    // Most strings pulled off the GE widget tree are not item names, and each miss costs a full
    // scan of the item database. Remember misses, but re-check them occasionally so names that
    // only failed because the item database had not loaded yet still resolve later.
    private static final long NEGATIVE_LOOKUP_TTL_MS = 60_000L;
    private static final int MAX_NEGATIVE_LOOKUPS = 2048;

    private final Map<String, Long> negativeLookupCache = new ConcurrentHashMap<>();
    private final Map<String, Integer> itemNameLookupCache;
    private final Map<Integer, String> itemNameCache;
    private final ItemManager itemManager;
    private final ClientThread clientThread;

    @Inject
    ItemLookup(ItemManager itemManager, ClientThread clientThread, PluginState state) {
        this.itemNameLookupCache = state.getItemNameLookupCache();
        this.itemNameCache = state.getItemNameCache();
        this.itemManager = itemManager;
        this.clientThread = clientThread;
    }

    private Integer findItemIdByExactName(String name) {
        if (name == null || itemManager == null) {
            return null;
        }
        for (ItemPrice price : itemManager.search(name)) {
            if (price.getName() != null && price.getName().equalsIgnoreCase(name)) {
                return price.getId();
            }
        }
        return null;
    }

    private String lookupItemName(int itemId) {
        if (itemManager == null || itemId <= 0) {
            return null;
        }
        ItemComposition composition = itemManager.getItemComposition(itemId);
        // Not getName(): on a free world that is "Twinflame staff (Members)", and a lapsed member's
        // offers still fill there. The name is cached for the session and sent to the website.
        return composition != null ? composition.getMembersName() : null;
    }

    private Integer lookupGeLimit(int itemId) {
        if (itemManager == null || itemId <= 0) {
            return null;
        }
        ItemStats stats = itemManager.getItemStats(itemId);
        if (stats != null && stats.getGeLimit() > 0) {
            return stats.getGeLimit();
        }
        return null;
    }

    private void onItemNameCacheUpdated() {
        GeLifecyclePlugin plugin = Access.plugin();
        PanelRefresh coordinator = plugin.getPanelRefreshCoordinator();
        if (coordinator != null) {
            coordinator.scheduleRefreshSoon(plugin.scheduler);
            coordinator.triggerStatsRefresh(plugin.scheduler);
        }
    }

    int resolveItemIdFromName(String name) {
        if (name == null) {
            return -1;
        }
        String key = name.trim().toLowerCase();
        if (key.isEmpty()) {
            return -1;
        }
        Integer cached = itemNameLookupCache != null ? itemNameLookupCache.get(key) : null;
        if (cached != null) {
            return cached;
        }
        long nowMs = System.currentTimeMillis();
        if (isKnownMiss(key, nowMs)) {
            return -1;
        }
        try {
            Integer resolved = findItemIdByExactName(name);
            if (resolved != null && resolved > 0) {
                negativeLookupCache.remove(key);
                if (itemNameLookupCache != null) {
                    itemNameLookupCache.put(key, resolved);
                }
                return resolved;
            }
        } catch (RuntimeException ignored) {
            // A lookup that throws is a miss like any other, and is remembered as one below.
        }
        rememberMiss(key, nowMs);
        return -1;
    }

    private boolean isKnownMiss(String key, long nowMs) {
        Long missedAtMs = negativeLookupCache.get(key);
        if (missedAtMs == null) {
            return false;
        }
        if (nowMs - missedAtMs < NEGATIVE_LOOKUP_TTL_MS) {
            return true;
        }
        negativeLookupCache.remove(key);
        return false;
    }

    private void rememberMiss(String key, long nowMs) {
        if (negativeLookupCache.size() >= MAX_NEGATIVE_LOOKUPS) {
            negativeLookupCache.clear();
        }
        negativeLookupCache.put(key, nowMs);
    }

    String lookupItemNameSafe(int itemId) {
        if (itemId <= 0) {
            return null;
        }
        try {
            return lookupItemName(itemId);
        } catch (RuntimeException ignored) {
            return null;
        }
    }

    Integer lookupGeLimitSafe(int itemId) {
        if (itemId <= 0) {
            return null;
        }
        try {
            Integer geLimit = lookupGeLimit(itemId);
            return geLimit != null && geLimit > 0 ? geLimit : null;
        } catch (RuntimeException ignored) {
            return null;
        }
    }

    void cacheItemName(int itemId) {
        if (itemId <= 0 || !canCacheItemNamesAsync()) {
            return;
        }
        if (itemNameCache != null && itemNameCache.containsKey(itemId)) {
            return;
        }
        clientThread.invokeLater(() -> {
            try {
                String name = lookupItemNameSafe(itemId);
                if (Str.isBlank(name)) {
                    return;
                }
                if (itemNameCache == null) {
                    return;
                }
                if (itemNameCache.putIfAbsent(itemId, name) == null) {
                    onItemNameCacheUpdated();
                }
            } catch (AssertionError | RuntimeException ignored) {
                // The name stays unknown, and the next sighting of the item asks again.
            }
        });
    }

    /** Whether there is anything to look a name up with, and a thread to do it on. */
    private boolean canCacheItemNamesAsync() {
        return itemManager != null && clientThread != null;
    }

    String getCachedItemName(int itemId) {
        if (itemId <= 0 || itemNameCache == null) {
            return null;
        }
        return itemNameCache.get(itemId);
    }
}

