package com.osrsfliphub;

import java.util.*;

final class ItemsResponseFactory {
    private ItemsResponseFactory() {
    }

    static ApiClient.ItemsResponse empty(long asOfMs, Long priceCacheMs) {
        return fromItems(Collections.emptyList(), asOfMs, priceCacheMs);
    }

    static ApiClient.ItemsResponse fromItems(List<FlipHubItem> items, long asOfMs, Long priceCacheMs) {
        int total = items != null ? items.size() : 0;
        return paged(items, 1, total, total, 1, asOfMs, priceCacheMs);
    }

    static ApiClient.ItemsResponse paged(List<FlipHubItem> items,
                                         int page,
                                         int pageSize,
                                         int totalItems,
                                         int totalPages,
                                         long asOfMs,
                                         Long priceCacheMs) {
        ApiClient.ItemsResponse response = new ApiClient.ItemsResponse();
        response.items = items != null ? new ArrayList<>(items) : Collections.emptyList();
        response.page = page;
        response.page_size = pageSize;
        response.total_items = totalItems;
        response.total_pages = totalPages;
        response.as_of_ms = asOfMs;
        response.price_cache_ms = priceCacheMs;
        return response;
    }
}

