package com.osrsfliphub;

import java.util.*;
import lombok.AllArgsConstructor;

/**
 * One conversion the player recorded themselves: the trades they bought the parts with, the
 * trades they sold the result with, and what the conversion itself cost.
 *
 * <p>This replaces guessing. The plugin used to watch the trade stream and infer that a set had
 * been assembled, which needed a table of 375 recipes, a matcher, a notion of how sure it was,
 * machinery for breaks whose pieces had not all sold yet, and a way for the player to dismiss a
 * wrong guess. All of that existed because the game never says you combined anything. Being told
 * instead of guessing removes the question.</p>
 *
 * <p>Trades are named by {@link TradeKey}, the same identity the stored trade list uses, with a
 * quantity, because one purchase can feed more than one conversion. A stored record is only
 * applied when every trade it names is still present and still has the quantity it claims.</p>
 */
@AllArgsConstructor
final class RecipeFlip {
    /** A quantity taken out of one stored trade. */
    @AllArgsConstructor
    static final class Part {
        TradeKey trade;
        int quantity;
        /**
         * What this much of the purchase cost. Only a move carries it, because the account the
         * stock went to prices it without the purchase in front of it; a recipe reads its coins
         * off the trade. Boxed so that a recipe's part is written exactly as it always was.
         */
        Long gp;

        Part() {
        }

        boolean isUsable() {
            return trade != null && quantity > 0;
        }
    }

    ConversionKind kind;
    /** What the player is making or taking apart, for the card to name. */
    String name;
    /** The purchases consumed. */
    List<Part> inputs;
    /** The sales the result went out through. */
    List<Part> outputs;
    /** Coins the conversion itself cost, such as a repair fee. Never negative. */
    long feeGp;
    /** When the player recorded it, used only to order equally-timed activities. */
    long recordedMs;
    /**
     * Set on a move and on nothing else: the account the purchases were handed to.
     *
     * <p>Each account keeps its own books, so items bought on one and sold on another were held
     * for ever by the first and sold out of nowhere by the second. A move names the purchases
     * and where they went, and no sales: here the purchases leave the books
     * ({@link RecipeFlipLedger}), there they arrive as if bought there
     * ({@link RecipeFlipLedger#received}), and that account's ordinary replay matches whatever it
     * sold, before the move was recorded or after. Boxed so a recipe is written as it always was.
     */
    Long toAccount;
    /**
     * Set on what is left of a record the player forgot, and on nothing else: the id the website
     * knows it by. Kept only to tell the website again each session, because the first telling
     * could be lost - made while unlinked, or in an upload that was refused - and the website then
     * kept the recipe for ever. With no kind and no trades it is unusable, so the ledgers pass over
     * it, and so does every older build, which drops it.
     */
    String voided;

    RecipeFlip() {
    }

    List<Part> inputParts() {
        return inputs != null ? inputs : new ArrayList<>();
    }

    List<Part> outputParts() {
        return outputs != null ? outputs : new ArrayList<>();
    }

    /**
     * Whether this is worth applying at all: a kind, at least one purchase and at least one sale,
     * every part naming a trade and a positive quantity. A move is the other way about: it has
     * no sales, and every purchase says what it cost.
     */
    boolean isUsable() {
        if (kind == null || inputParts().isEmpty() || outputParts().isEmpty() == (toAccount == null)) {
            return false;
        }
        for (Part part : inputParts()) {
            if (!part.isUsable() || toAccount != null && part.gp == null) {
                return false;
            }
        }
        for (Part part : outputParts()) {
            if (!part.isUsable()) {
                return false;
            }
        }
        return feeGp >= 0L;
    }

    /** Every trade this record touches, on either side. */
    List<TradeKey> trades() {
        List<TradeKey> out = new ArrayList<>(inputParts().size() + outputParts().size());
        for (Part part : inputParts()) {
            out.add(part.trade);
        }
        for (Part part : outputParts()) {
            out.add(part.trade);
        }
        return out;
    }

    /** The item the activity is filed against: what was produced, or what was taken apart. */
    int subjectItemId() {
        List<Part> subject = outputParts().size() == 1 ? outputParts() : inputParts();
        return subject.isEmpty() || subject.get(0).trade == null ? 0 : subject.get(0).trade.itemId;
    }
}

